"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  ActivitySceneContext,
  useActivityPresence,
  useActivityScene,
  type ActivityLayout,
} from "@/lib/cojeev/activity-motion";
import { MARK_PATHS } from "@/lib/cojeev/milestone-travel";
import { useChoreography } from "@/lib/cojeev-motion/choreography";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";
import { useGuidanceMotion } from "@/lib/cojeev-motion/use-guidance-motion";
import { AnimatedIcon } from "@/components/ui/animated-icon";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge, type BadgeProps } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Empty, EmptyDescription, EmptyTitle } from "@/components/ui/empty";
import { ItemContent, ItemDescription, ItemTitle } from "@/components/ui/item";
import { MotionPresence } from "@/components/ui/presence";
import { BodySecondary, Meta, Title } from "@/components/ui/typography";

export type ActivityEntry = {
  id: string;
  title: React.ReactNode;
  description?: React.ReactNode;
  actor?: { name: string; initials?: string; avatarSrc?: string };
  timestamp?: React.ReactNode;
  /** Machine-readable time matching the caller's timestamp label. */
  dateTime?: string;
  /** Optional visible group heading; shown where a consecutive group begins. */
  group?: string;
  badge?: { label: React.ReactNode; variant?: BadgeProps["variant"] };
  /** Additional supplied details or native actions, kept in document flow. */
  content?: React.ReactNode;
};
export type ActivityFeedProps = Omit<
  React.ComponentProps<"section">,
  "children" | "title"
> & {
  /** Caller supplies the chronological order; the feed never reorders entries. */
  entries: readonly ActivityEntry[];
  title?: React.ReactNode;
  description?: React.ReactNode;
  empty?: React.ReactNode;
  /** Omit to show every supplied entry, including later appends. */
  initialVisible?: number;
  pageSize?: number;
  showMoreLabel?: React.ReactNode;
  /**
   * Look of the history. "thread": one row per entry on a living thread. "ledger": dense,
   * one avatar per run of entries by the same actor within a group, pinned group labels.
   * "bursts": one card per actor's updates made within 30 minutes of each other; two or
   * more become a native disclosure titled "N updates".
   */
  variant?: "thread" | "ledger" | "bursts";
};

/* ---------- grouping: the caller's order is kept; consecutive entries are only gathered ---------- */
const BURST_SPAN = 30 * 60 * 1000;
const actorOf = (entry: ActivityEntry) => entry.actor?.name.trim() ?? "";
const timeOf = (entry: ActivityEntry) => {
  const t = entry.dateTime ? Date.parse(entry.dateTime) : NaN;
  return Number.isFinite(t) ? t : null;
};
function joins(layout: ActivityLayout, newer: ActivityEntry, entry: ActivityEntry) {
  if (layout === "thread" || actorOf(newer) !== actorOf(entry)) return false;
  if (layout === "ledger") return true;
  // A burst needs both times; an entry without one stands alone.
  const a = timeOf(newer),
    b = timeOf(entry);
  return a !== null && b !== null && Math.abs(a - b) <= BURST_SPAN;
}
function runs<T>(items: readonly T[], same: (newer: T, item: T) => boolean) {
  const out: T[][] = [];
  for (const item of items) {
    const last = out[out.length - 1];
    if (last && same(last[last.length - 1], item)) last.push(item);
    else out.push([item]);
  }
  return out;
}
type Keys = ReadonlyMap<string, string>;
/** A group keeps the key of any entry it held before, so prepends and reveals never remount it. */
function keyGroups(
  groups: readonly (readonly ActivityEntry[])[],
  previous: Keys,
  prefix: string,
) {
  const used = new Set<string>();
  return groups.map((group) => {
    let key = group
      .map((entry) => previous.get(entry.id))
      .find((k): k is string => k !== undefined && !used.has(k));
    if (key === undefined) {
      key = `${prefix}${group[0].id}`;
      while (used.has(key)) key += "+";
    }
    used.add(key);
    return key;
  });
}
const sameKeys = (a: Keys, b: Keys) =>
  a.size === b.size && [...a].every(([id, key]) => b.get(id) === key);
type Cluster = { key: string; entries: ActivityEntry[] };
type Day = { key: string; label?: string; clusters: Cluster[] };

function count(value: number | undefined, fallback: number) {
  return value !== undefined && Number.isFinite(value)
    ? Math.max(1, Math.floor(value))
    : fallback;
}
const initialsOf = (name: string) =>
  name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => Array.from(part)[0])
    .join("");

/** An actor's avatar, or the four-point star for the product's own entries. */
function Mark({ actor }: { actor?: ActivityEntry["actor"] }) {
  if (!actor)
    return (
      <span
        className="v-activity-feed__mark v-activity-feed__marker"
        data-brand=""
      >
        <svg viewBox="-18 -18 36 36" focusable="false" aria-hidden="true">
          <path d={MARK_PATHS.star} />
        </svg>
      </span>
    );
  return (
    <span className="v-activity-feed__mark">
      <Avatar variant="sm">
        {actor.avatarSrc && <AvatarImage src={actor.avatarSrc} alt="" />}
        <AvatarFallback>{actor.initials ?? initialsOf(actor.name)}</AvatarFallback>
      </Avatar>
    </span>
  );
}

function EntryContent({ entry }: { entry: ActivityEntry }) {
  return (
    <ItemContent className="v-activity-feed__content">
      <div className="v-activity-feed__entry-heading">
        <ItemTitle className="v-activity-feed__title">{entry.title}</ItemTitle>
        {entry.badge && (
          <Badge
            size="sm"
            variant={entry.badge.variant ?? "cream"}
            className="v-activity-feed__badge"
          >
            {entry.badge.label}
          </Badge>
        )}
      </div>
      {entry.description && (
        <ItemDescription className="v-activity-feed__description">
          {entry.description}
        </ItemDescription>
      )}
      {(entry.actor || entry.timestamp) && (
        <div className="v-activity-feed__meta">
          {entry.actor && (
            <Meta className="v-activity-feed__who">{entry.actor.name}</Meta>
          )}
          {entry.actor && entry.timestamp && (
            <span aria-hidden="true" className="v-activity-feed__sep">
              ·
            </span>
          )}
          <span aria-hidden="true" className="v-activity-feed__live" />
          {entry.timestamp && (
            <time dateTime={entry.dateTime}>
              <Meta>{entry.timestamp}</Meta>
            </time>
          )}
        </div>
      )}
      {entry.content && (
        <div className="v-activity-feed__details">{entry.content}</div>
      )}
    </ItemContent>
  );
}

function Row({
  entry,
  layout,
  label,
}: {
  entry: ActivityEntry;
  layout: ActivityLayout;
  label?: string;
}) {
  const [ref, leaving] = useActivityPresence<HTMLLIElement>();
  return (
    <li
      ref={ref}
      tabIndex={-1}
      data-activity-entry={entry.id}
      data-leaving={leaving || undefined}
      inert={leaving || undefined}
      aria-hidden={leaving || undefined}
      className="v-activity-feed__entry"
    >
      {label && <div className="v-activity-feed__group">{label}</div>}
      {/* Spacing lives inside, so the row itself can close to nothing. */}
      <div className="v-activity-feed__inner">
        {layout === "thread" && (
          <div className="v-activity-feed__portrait" aria-hidden="true">
            <Mark actor={entry.actor} />
          </div>
        )}
        {layout === "ledger" && (
          <span className="v-activity-feed__wash" aria-hidden="true" />
        )}
        <EntryContent entry={entry} />
      </div>
    </li>
  );
}

function Rows({
  entries,
  layout,
  id,
}: {
  entries: readonly ActivityEntry[];
  layout: ActivityLayout;
  id?: string;
}) {
  return (
    <ol id={id} className="v-activity-feed__rows" role="list">
      <MotionPresence>
        {entries.map((entry) => (
          <Row key={entry.id} entry={entry} layout={layout} />
        ))}
      </MotionPresence>
    </ol>
  );
}

function ClusterBox({
  cluster,
  layout,
}: {
  cluster: Cluster;
  layout: ActivityLayout;
}) {
  const [ref, leaving] = useActivityPresence<HTMLLIElement>();
  const scene = React.useContext(ActivitySceneContext);
  const rowsId = React.useId();
  const actor = cluster.entries[0].actor;
  const name = actor?.name.trim();
  const burst = layout === "bursts" && cluster.entries.length > 1;
  const toggle = (event: React.MouseEvent<HTMLElement>) => {
    const details = event.currentTarget.parentElement;
    if (details instanceof HTMLDetailsElement && scene.current?.toggle(details))
      event.preventDefault();
  };
  return (
    <li
      ref={ref}
      data-leaving={leaving || undefined}
      inert={leaving || undefined}
      aria-hidden={leaving || undefined}
      data-burst={burst || undefined}
      className="v-activity-feed__cluster"
    >
      {layout === "ledger" ? (
        <div className="v-activity-feed__cluster-inner">
          <div className="v-activity-feed__portrait" aria-hidden="true">
            <Mark actor={actor} />
          </div>
          <div className="v-activity-feed__cluster-body">
            {/* Each row keeps the actor in its own accessible text. */}
            {name && (
              <p className="v-activity-feed__cluster-name" aria-hidden="true">
                {name}
              </p>
            )}
            <Rows entries={cluster.entries} layout={layout} />
          </div>
        </div>
      ) : (
        <>
          {burst ? (
            <details open className="v-activity-feed__burst">
              <summary
                className="v-activity-feed__card-head"
                aria-controls={rowsId}
                onClick={toggle}
              >
                <span aria-hidden="true">
                  <Mark actor={actor} />
                </span>
                <span className="v-activity-feed__card-who">
                  {name && (
                    <span className="v-activity-feed__card-name">{name}</span>
                  )}
                  <span className="v-activity-feed__card-count">
                    {cluster.entries.length} updates
                  </span>
                </span>
                <svg
                  className="v-activity-feed__chevron"
                  viewBox="0 0 16 16"
                  aria-hidden="true"
                  focusable="false"
                >
                  <path d="M4 6l4 4 4-4" />
                </svg>
              </summary>
            </details>
          ) : (
            <div className="v-activity-feed__card-head" aria-hidden="true">
              <Mark actor={actor} />
              {name && (
                <span className="v-activity-feed__card-who">
                  <span className="v-activity-feed__card-name">{name}</span>
                </span>
              )}
            </div>
          )}
          {/* Rows stay outside the disclosure so a card becoming a burst keeps them mounted. */}
          <Rows id={rowsId} entries={cluster.entries} layout={layout} />
        </>
      )}
    </li>
  );
}

function DayBox({ day, layout }: { day: Day; layout: ActivityLayout }) {
  const [ref, leaving] = useActivityPresence<HTMLLIElement>();
  return (
    <li
      ref={ref}
      data-leaving={leaving || undefined}
      inert={leaving || undefined}
      aria-hidden={leaving || undefined}
      className="v-activity-feed__day"
    >
      {day.label && <div className="v-activity-feed__group">{day.label}</div>}
      <ol className="v-activity-feed__clusters" role="list">
        <MotionPresence>
          {day.clusters.map((cluster) => (
            <ClusterBox key={cluster.key} cluster={cluster} layout={layout} />
          ))}
        </MotionPresence>
      </ol>
    </li>
  );
}

export function ActivityFeed({
  entries,
  title,
  description,
  empty,
  initialVisible,
  pageSize = 3,
  showMoreLabel,
  variant,
  className,
  ref,
  "aria-label": ariaLabel,
  "aria-labelledby": labelledBy,
  ...props
}: ActivityFeedProps) {
  const layout: ActivityLayout =
    variant === "ledger" || variant === "bursts" ? variant : "thread";
  const titleId = React.useId();
  const listId = React.useId();
  const section = React.useRef<HTMLElement | null>(null);
  const setSection = React.useCallback(
    (node: HTMLElement | null) => {
      section.current = node;
      return assignMotionRef(ref, node);
    },
    [ref],
  );
  const layer = React.useRef<SVGSVGElement | null>(null);
  const list = React.useRef<HTMLOListElement>(null);
  const focusIndex = React.useRef<number | null>(null);
  const revealed = React.useRef<string[]>([]);
  const [windowState, setWindowState] = React.useState(() => ({
    ids: entries.map((entry) => entry.id),
    limit: count(initialVisible, Infinity),
  }));
  const ids = entries.map((entry) => entry.id);
  let limit = windowState.limit;
  if (
    ids.length !== windowState.ids.length ||
    ids.some((id, index) => id !== windowState.ids[index])
  ) {
    const oldFirst = windowState.ids[0],
      firstIndex = ids.indexOf(oldFirst),
      previous = new Set(windowState.ids);
    const prepended =
      firstIndex > 0
        ? ids.slice(0, firstIndex).filter((id) => !previous.has(id)).length
        : 0;
    limit += prepended;
    // Reconcile before committing the new list: existing entries never unmount
    // for a frame merely because a new update was prepended.
    setWindowState({ ids, limit });
  }
  const [announcement, setAnnouncement] = React.useState("");
  const visible = entries.slice(0, limit);
  const remaining = entries.length - visible.length;
  const nextPage = Math.min(remaining, count(pageSize, 3));

  // Days and runs keep their identity across prepends and reveals.
  const [keys, setKeys] = React.useState<{ days: Keys; clusters: Keys }>(
    () => ({ days: new Map(), clusters: new Map() }),
  );
  let days: Day[] = [];
  if (layout !== "thread") {
    const dayRuns = runs(visible, (a, b) => a.group === b.group);
    const dayKeys = keyGroups(dayRuns, keys.days, "d:");
    const clusterRuns = dayRuns.map((day) =>
      runs(day, (a, b) => joins(layout, a, b)),
    );
    const clusterKeys = keyGroups(clusterRuns.flat(), keys.clusters, "c:");
    let c = 0;
    days = dayRuns.map((day, i) => ({
      key: dayKeys[i],
      label: day[0].group,
      clusters: clusterRuns[i].map((entries) => ({
        key: clusterKeys[c++],
        entries,
      })),
    }));
    const next = {
      days: new Map(
        days.flatMap((d) =>
          d.clusters.flatMap((cl) => cl.entries.map((e) => [e.id, d.key] as const)),
        ),
      ),
      clusters: new Map(
        days.flatMap((d) =>
          d.clusters.flatMap((cl) => cl.entries.map((e) => [e.id, cl.key] as const)),
        ),
      ),
    };
    if (!sameKeys(next.days, keys.days) || !sameKeys(next.clusters, keys.clusters))
      setKeys(next);
  }

  React.useLayoutEffect(() => {
    if (focusIndex.current === null) return;
    const target = list.current?.querySelectorAll<HTMLElement>(
      "[data-activity-entry]:not([data-leaving])",
    )[focusIndex.current];
    // A revealed entry inside a closed burst opens it, so focus lands on something visible.
    const burst = target
      ?.closest(".v-activity-feed__cluster")
      ?.querySelector<HTMLDetailsElement>(":scope > details");
    if (burst && !burst.open) burst.open = true;
    target?.focus();
    focusIndex.current = null;
  }, [visible.length]);

  const { quiet: globalQuiet } = useChoreography();
  const { quiet, enabled, inView } = useGuidanceMotion(section);
  const live = !quiet && enabled && inView;
  const scene = useActivityScene(section, {
    layout,
    ids: visible.map((entry) => entry.id),
    brand: new Set(visible.filter((e) => !e.actor).map((e) => e.id)),
    allowed: live,
    breathe: live,
    layer,
    takeRevealed: () => {
      const taken = revealed.current;
      revealed.current = [];
      return taken;
    },
  });

  const reveal = () => {
    focusIndex.current = visible.length;
    const nextCount = visible.length + nextPage;
    revealed.current = entries
      .slice(visible.length, nextCount)
      .map((entry) => entry.id);
    setWindowState((value) => ({ ...value, limit: nextCount }));
    setAnnouncement(`${nextCount} of ${entries.length} activities shown.`);
  };
  return (
    <section
      {...props}
      ref={setSection}
      data-slot="activity-feed"
      data-variant={layout}
      data-motion-quiet={globalQuiet || undefined}
      aria-label={ariaLabel ?? (!title && !labelledBy ? "Activity" : undefined)}
      aria-labelledby={labelledBy ?? (title ? titleId : undefined)}
      className={cn("v-activity-feed", className)}
    >
      {(title || description) && (
        <header className="v-activity-feed__header">
          {title && (
            <div className="v-activity-feed__heading">
              <Title id={titleId}>{title}</Title>
              <Badge
                variant="count"
                aria-label={`${entries.length} activities`}
              >
                {entries.length}
              </Badge>
            </div>
          )}
          {description && <BodySecondary as="div">{description}</BodySecondary>}
        </header>
      )}
      {entries.length === 0 ? (
        (empty ?? (
          <Empty>
            <EmptyTitle>No activity yet</EmptyTitle>
            <EmptyDescription>
              Updates appear here as they are added.
            </EmptyDescription>
          </Empty>
        ))
      ) : (
        <ActivitySceneContext.Provider value={scene}>
          <div className="v-activity-feed__body">
            <ol
              ref={list}
              id={listId}
              className="v-activity-feed__list"
              role="list"
            >
              <MotionPresence>
                {layout === "thread"
                  ? visible.map((entry, index) => (
                      <Row
                        key={entry.id}
                        entry={entry}
                        layout={layout}
                        label={
                          entry.group &&
                          entry.group !== visible[index - 1]?.group
                            ? entry.group
                            : undefined
                        }
                      />
                    ))
                  : days.map((day) => (
                      <DayBox key={day.key} day={day} layout={layout} />
                    ))}
              </MotionPresence>
            </ol>
            {layout === "thread" && (
              <svg
                ref={layer}
                className="v-activity-feed__thread"
                aria-hidden="true"
                focusable="false"
              />
            )}
          </div>
          {remaining > 0 && (
            <footer className="v-activity-feed__footer">
              <Button
                variant="secondary"
                size="sm"
                aria-controls={listId}
                onClick={reveal}
              >
                <AnimatedIcon name="chevron-down" size="sm" preset="bounce" />
                {showMoreLabel ?? `Show ${nextPage} more`}
              </Button>
              <Meta>
                {visible.length} of {entries.length}
              </Meta>
            </footer>
          )}
        </ActivitySceneContext.Provider>
      )}
      <span role="status" aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </section>
  );
}

"use client";

import * as React from "react";
import { usePresence } from "motion/react";
import { path as outline, spring, type Spring } from "@/lib/cojeev-motion/geometry";
import {
  cancelMotion,
  registerMotionClock,
  scheduleMotion,
  type MotionTimer,
} from "@/lib/cojeev-motion/clock";
import { MARK_POINTS } from "@/lib/cojeev/milestone-travel";

export type ActivityLayout = "thread" | "ledger" | "bursts";
type Pts = readonly (readonly number[])[];
type Pair = readonly [number, number];

/* ---------- motion table: every spring is [stiffness, damping ratio] ---------- */
const SPR = {
  remove: [300, 1], // a removed row, run, card or day closes to zero
  restore: [260, 0.78], // a removal reversed before it finished
  markIn: [320, 0.6], // a revealed thread marker pops in
  markOut: [380, 0.8], // a removed thread marker folds away
  thread: {
    arrive: [210, 0.72], // the new row makes room; content fades in at 55 %
    threadUp: [150, 0.95], // the thread grows up to meet it from 80 %
    seed: [320, 0.6], // the seed appears
    morph: [220, 0.6], // seed to four-point star
    starGrow: [260, 0.5],
    spin: [170, 0.5],
    handoff: [380, 1], // the star yields to the avatar
    avatarIn: [340, 0.5],
    unfurl: [240, 0.85],
    threadDown: [220, 1],
  },
  ledger: { arrive: [300, 1], wash: [150, 1], unfurl: [300, 1] },
  bursts: {
    arrive: [240, 0.58], // the card stretches to take the new line
    gulp: [260, 0.45], // a closed burst takes a line without opening
    unfurl: [240, 0.62],
    open: [260, 0.62],
    close: [320, 0.9],
  },
} as const satisfies Record<string, unknown>;
const T = {
  bloomMorphAt: 170,
  unfurlStagger: 70,
  unfurlMax: 3,
  breathFor: 45000,
  waitMax: 4,
};
const GAP = 18; // thread clearance around a 28 px marker
const MARK_SCALE = 30 / 36; // marks paint their -18..18 outline at 30 px
const PEBBLE = MARK_POINTS.pebble,
  STAR = MARK_POINTS.star;

/* ---------- one rAF loop for every feed, steppable by the shared motion clock ---------- */
type Scene = { frame: (dt: number) => boolean };
const scenes = new Set<Scene>();
let clock: number | null = null,
  previous: number | null = null,
  raf = 0;
function stopLoop() {
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
}
function tick(t: number) {
  const dt = previous === null ? 0 : Math.max(0, (t - previous) / 1000);
  previous = t;
  let active = false;
  scenes.forEach((s) => {
    active = s.frame(dt) || active;
  });
  return active;
}
function wake() {
  if (clock !== null || raf || !scenes.size || document.hidden) return;
  if (previous === null) previous = performance.now();
  raf = requestAnimationFrame((t) => {
    raf = 0;
    if (tick(t)) wake();
    else previous = null;
  });
}
if (typeof window !== "undefined")
  registerMotionClock((t) => {
    stopLoop();
    if (t === null) {
      clock = null;
      previous = null;
      wake();
    } else {
      if (clock === null) previous = t;
      clock = t;
      tick(t);
    }
  });

/* ---------- helpers ---------- */
const NS = "http://www.w3.org/2000/svg";
const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const f2 = (n: number) => n.toFixed(2);
const S = ([k, z]: Pair, x = 0): Spring => ({ x, v: 0, to: x, k, z });
const tune = (s: Spring, [k, z]: Pair) => {
  s.k = k;
  s.z = z;
  return s;
};
const rest = (s: Spring) => s.x === s.to && s.v === 0;
const lerpPts = (A: Pts, B: Pts, m: number) =>
  A.map((p, i) => [p[0] + (B[i][0] - p[0]) * m, p[1] + (B[i][1] - p[1]) * m]);
const hash = (s: string) => {
  let x = 2166136261;
  for (const c of s) x = Math.imul(x ^ c.charCodeAt(0), 16777619);
  return x >>> 0;
};
/** Natural height of a box the scene is sizing, read without a visible frame. */
function natural(el: HTMLElement) {
  const was = el.style.height;
  el.style.height = "";
  const h = el.getBoundingClientRect().height;
  el.style.height = was;
  return h;
}
const ROW = "[data-activity-entry]";
const markOf = (row: Element) =>
  row.querySelector<HTMLElement>(".v-activity-feed__mark");

type Height = {
  s: Spring;
  to: number | "auto";
  onFrame?: (p: number) => void;
  done?: () => void;
};
type Anim = { tick: (dt: number) => boolean; done?: () => void };
type Wait = { when: () => boolean; run: () => void; left: number };
type Grow = { s: Spring; dir: "up" | "down" };
type Blob = {
  row: HTMLElement;
  s: Spring;
  m: Spring;
  rot: Spring;
  A: Pts;
  B: Pts;
  fill: "pink" | "olive";
  el: SVGPathElement;
};
export type ActivitySync = {
  layout: ActivityLayout;
  /** Visible entry ids in order. */
  ids: readonly string[];
  /** Ids revealed by the last Show more, consumed by this sync. */
  revealed: readonly string[];
  /** Brand entries keep the star as their mark. */
  brand: ReadonlySet<string>;
  allowed: boolean;
  breathe: boolean;
  layer: SVGSVGElement | null;
};

function createScene(host: HTMLElement) {
  let layout: ActivityLayout = "thread",
    layer: SVGSVGElement | null = null,
    spine: SVGGElement | null = null,
    seeds: SVGGElement | null = null,
    gen = 0,
    ids: string[] = [],
    brand: ReadonlySet<string> = new Set(),
    started = false,
    allowed = false,
    breatheOn = false,
    breathId: string | null = null,
    breathTimer: MotionTimer | null = null;
  const heights = new Map<HTMLElement, Height>();
  const anims = new Set<Anim>();
  const waits = new Set<Wait>();
  const timers = new Set<MotionTimer>();
  const grow = new Map<string, Grow>();
  const blobs = new Set<Blob>();
  const markScale = new Map<HTMLElement, number>();
  const known = new WeakSet<Element>();
  const segments: SVGPathElement[] = [];

  const rowOf = (id: string) =>
    host.querySelector<HTMLElement>(
      `[data-activity-entry="${CSS.escape(id)}"]:not([data-leaving])`,
    );
  const after = (ms: number, fn: () => void) => {
    const g = gen;
    const timer = scheduleMotion(() => {
      timers.delete(timer);
      if (g !== gen) return;
      fn();
      wake();
    }, ms);
    timers.add(timer);
  };
  const until = (when: () => boolean, fn: () => void) => {
    const g = gen;
    waits.add({ when, run: () => g === gen && fn(), left: T.waitMax });
    wake();
  };
  const run = (a: Anim) => {
    anims.add(a);
    wake();
    return a;
  };
  const tween = (ss: Spring[], paint?: () => void, done?: () => void) =>
    run({
      tick: (dt) => {
        ss.forEach((s) => spring(s, dt));
        paint?.();
        return !ss.every(rest);
      },
      done,
    });

  /* one height owner per box: interruptible, keeps velocity on retarget, "auto" chases the content */
  function animHeight(
    el: HTMLElement,
    o: {
      from?: number;
      to?: number | "auto";
      k: Pair;
      kick?: number;
      onFrame?: (p: number) => void;
      done?: () => void;
    },
  ) {
    let a = heights.get(el);
    if (!a) {
      const x = o.from ?? el.getBoundingClientRect().height;
      a = { s: S(o.k, x), to: "auto" };
      heights.set(el, a);
    } else if (o.from !== undefined) a.s.x = o.from;
    tune(a.s, o.k).v += o.kick ?? 0;
    a.to = o.to ?? "auto";
    a.onFrame = o.onFrame;
    a.done = o.done;
    el.setAttribute("data-moving", "");
    el.style.height = `${f2(Math.max(0, a.s.x))}px`;
    wake();
  }
  function hold(el: HTMLElement, h: number) {
    el.setAttribute("data-moving", "");
    el.style.height = `${f2(Math.max(0, h))}px`;
  }
  function stepHeight(el: HTMLElement, a: Height, dt: number) {
    const target = a.to === "auto" ? natural(el) : a.to;
    a.s.to = target;
    spring(a.s, dt);
    // Pixel boxes settle at a tenth of a pixel; the snap is invisible.
    if (Math.abs(a.s.to - a.s.x) < 0.1 && Math.abs(a.s.v) < 1) {
      a.s.x = a.s.to;
      a.s.v = 0;
    }
    el.style.height = `${f2(Math.max(0, a.s.x))}px`;
    a.onFrame?.(target ? clamp(a.s.x / target) : 1);
    if (rest(a.s)) finishHeight(el, a);
  }
  function finishHeight(el: HTMLElement, a: Height) {
    heights.delete(el);
    a.onFrame?.(1);
    // A box closing to a number keeps it: its owner removes or re-renders the box next.
    if (a.to === "auto") {
      el.style.height = "";
      el.removeAttribute("data-moving");
    }
    a.done?.();
  }

  /* ---------- thread layer: the spine between marks and the blooming seed ---------- */
  function draw() {
    if (!layer || !spine || !seeds) return;
    if (layout !== "thread") {
      segments.forEach((p) => p.setAttribute("display", "none"));
      return;
    }
    const bb = layer.getBoundingClientRect();
    const pts: { key: string; x: number; y: number; ms: number }[] = [];
    // A leaving row has no place in the thread: its neighbours join directly.
    for (const row of host.querySelectorAll<HTMLElement>(
      `${ROW}:not([data-leaving])`,
    )) {
      const m = markOf(row);
      if (!m) continue;
      const rc = m.getBoundingClientRect();
      if (!rc.width) continue;
      pts.push({
        key: row.dataset.activityEntry ?? "",
        x: rc.left - bb.left + rc.width / 2,
        y: rc.top - bb.top + rc.height / 2,
        ms: clamp(markScale.get(row) ?? 1),
      });
    }
    let n = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i],
        b = pts[i + 1];
      // the gap shrinks with a growing marker, so the thread meets the seed
      const y0 = a.y + GAP * a.ms,
        y1 = b.y - GAP * b.ms,
        D = y1 - y0;
      if (D < 3) continue;
      const key = `${a.key}>${b.key}`,
        gr = grow.get(key),
        g = gr ? clamp(gr.s.x) : 1;
      if (g <= 0.001) continue;
      const p =
        segments[n] ??
        (segments[n] = spine.appendChild(document.createElementNS(NS, "path")));
      n++;
      p.setAttribute("class", "v-activity-feed__spine");
      // two cubic halves, up to 3 px sideways, the side seeded by the pair
      const w = (hash(key) & 1 ? 1 : -1) * Math.min(3, D / 14),
        x = a.x,
        up = gr?.dir === "up",
        s = up ? y1 : y0,
        d = up ? -D : D;
      p.setAttribute(
        "d",
        `M${f2(x)} ${f2(s)}C${f2(x)} ${f2(s + 0.26 * d)} ${f2(x + w)} ${f2(s + 0.31 * d)} ${f2(x)} ${f2(s + 0.5 * d)}C${f2(x - w)} ${f2(s + 0.69 * d)} ${f2(x)} ${f2(s + 0.75 * d)} ${f2(x)} ${f2(s + d)}`,
      );
      if (gr) {
        const L = p.getTotalLength();
        p.setAttribute("stroke-dasharray", `${f2(L)} ${f2(L + 8)}`);
        p.setAttribute("stroke-dashoffset", f2(L * (1 - g)));
      } else {
        p.removeAttribute("stroke-dasharray");
        p.removeAttribute("stroke-dashoffset");
      }
      p.removeAttribute("display");
    }
    for (let i = n; i < segments.length; i++)
      segments[i].setAttribute("display", "none");
    for (const b of blobs) {
      const m = markOf(b.row);
      if (!m) continue;
      const rc = m.getBoundingClientRect(),
        x = rc.left - bb.left + rc.width / 2,
        y = rc.top - bb.top + rc.height / 2;
      b.el.setAttribute(
        "transform",
        `translate(${f2(x)} ${f2(y)}) scale(${(MARK_SCALE * Math.max(0, b.s.x)).toFixed(3)}) rotate(${f2(b.rot.x)})`,
      );
      b.el.setAttribute(
        "d",
        outline(lerpPts(b.A, b.B, clamp(b.m.x, -0.25, 1.25)), true),
      );
      b.el.setAttribute("data-fill", b.fill);
    }
  }
  function holdThread(key: string, dir: Grow["dir"]) {
    const gr: Grow = { s: S([1, 1], 0), dir };
    grow.set(key, gr);
    return gr;
  }
  function releaseThread(key: string, gr: Grow, k: Pair) {
    tune(gr.s, k).to = 1;
    tween([gr.s], undefined, () => {
      if (grow.get(key) === gr) grow.delete(key);
    });
  }
  const scaleMark = (row: HTMLElement, scale: number) => {
    const m = markOf(row);
    if (m) m.style.transform = scale === 1 ? "" : `scale(${scale.toFixed(3)})`;
  };
  const setMark = (row: HTMLElement, scale: number) => {
    markScale.set(row, scale);
    scaleMark(row, scale);
  };
  const showMark = (row: HTMLElement) => {
    row.removeAttribute("data-mark");
    setMark(row, 1);
    markScale.delete(row);
  };
  /** The marker blooms from a seed through the four-point star; brand rows keep the star. */
  function bloom(row: HTMLElement, isBrand: boolean) {
    if (!seeds) return showMark(row);
    const P = SPR.thread;
    const b: Blob = {
      row,
      s: S(P.seed),
      m: S(P.morph),
      rot: S(P.spin),
      A: PEBBLE,
      B: PEBBLE,
      fill: "pink",
      el: seeds.appendChild(document.createElementNS(NS, "path")),
    };
    b.el.setAttribute("class", "v-activity-feed__seed");
    b.s.to = 0.62;
    blobs.add(b);
    const av = S(P.avatarIn);
    const drop = () => {
      blobs.delete(b);
      b.el.remove();
    };
    run({
      tick: (dt) => {
        [b.s, b.m, b.rot, av].forEach((s) => spring(s, dt));
        if (av.x || av.v) scaleMark(row, av.x);
        markScale.set(row, Math.max(av.x, b.s.x * 0.9));
        return blobs.has(b) || !rest(av);
      },
      done: () => {
        drop();
        showMark(row);
      },
    });
    after(T.bloomMorphAt, () => {
      b.B = STAR;
      b.fill = "olive";
      b.m.to = 1;
      tune(b.s, P.starGrow).to = 1;
      b.rot.to = 90;
      until(
        () => b.m.x > 0.97 && Math.abs(b.s.x - 1) < 0.05,
        () => {
          if (isBrand) {
            until(
              () => rest(b.s) && rest(b.rot) && rest(b.m),
              () => {
                row.removeAttribute("data-mark");
                av.x = av.to = 1;
                av.v = 0;
                drop();
              },
            );
            return;
          }
          row.removeAttribute("data-mark");
          av.x = 0.35;
          av.to = 1;
          tune(b.s, P.handoff).to = 0;
          until(() => b.s.x < 0.02, drop);
        },
      );
    });
  }
  function markIn(row: HTMLElement) {
    row.removeAttribute("data-mark");
    const ms = S(SPR.markIn, 0.4);
    ms.to = 1;
    tween(
      [ms],
      () => setMark(row, ms.x),
      () => showMark(row),
    );
  }

  /* ---------- which box opens: a new day, else a new run or card, else the row ---------- */
  function boxFor(row: HTMLElement) {
    if (layout === "thread") return row;
    const cluster = row.closest<HTMLElement>(".v-activity-feed__cluster"),
      day = row.closest<HTMLElement>(".v-activity-feed__day");
    if (day && !known.has(day)) return day;
    if (cluster && (layout === "bursts" || !known.has(cluster))) return cluster;
    return row;
  }
  /** Where a box starts: zero when it is new, else its height without the new rows. */
  function startOf(box: HTMLElement, rows: HTMLElement[]) {
    if (rows.includes(box) || !known.has(box)) return 0;
    const added = rows
      .filter((r) => box.contains(r))
      .reduce((sum, r) => sum + r.getBoundingClientRect().height, 0);
    return Math.max(0, box.getBoundingClientRect().height - added);
  }
  const closedBurst = (row: HTMLElement) => {
    const d = row
      .closest(".v-activity-feed__cluster")
      ?.querySelector<HTMLDetailsElement>(":scope > details");
    return !!d && (!d.open || d.hasAttribute("data-closing"));
  };
  function wash(row: HTMLElement) {
    const w = row.querySelector<HTMLElement>(".v-activity-feed__wash");
    if (!w) return;
    const s = S(SPR.ledger.wash);
    s.to = 1;
    w.setAttribute("data-on", "");
    w.style.clipPath = "inset(0 100% 0 0 round 8px)";
    tween(
      [s],
      () => {
        w.style.clipPath = `inset(0 ${f2((1 - s.x) * 100)}% 0 0 round 8px)`;
      },
      () => {
        // the fade back runs in CSS within the shared draw duration
        w.style.clipPath = "";
        w.removeAttribute("data-on");
      },
    );
  }

  /* ---------- arrival: a live prepend ---------- */
  function arrive(fresh: string[]) {
    const rows = fresh
      .map((id) => rowOf(id))
      .filter((r): r is HTMLElement => !!r);
    if (layout === "thread") {
      for (const row of rows) {
        const id = row.dataset.activityEntry ?? "",
          next = ids[ids.indexOf(id) + 1],
          key = next !== undefined ? `${id}>${next}` : null,
          gr = key ? holdThread(key, "up") : null,
          isBrand = brand.has(id);
        row.setAttribute("data-mark", "hidden");
        row.setAttribute("data-arriving", "");
        markScale.set(row, 0);
        let shown = false,
          threaded = false;
        animHeight(row, {
          from: 0,
          k: SPR.thread.arrive,
          onFrame: (p) => {
            if (!shown && p > 0.55) {
              shown = true;
              row.removeAttribute("data-arriving");
            }
            if (!threaded && p > 0.8) {
              threaded = true;
              if (!gr || !key) return bloom(row, isBrand);
              releaseThread(key, gr, SPR.thread.threadUp);
              until(
                () => gr.s.x > 0.85,
                () => bloom(row, isBrand),
              );
            }
          },
        });
      }
      return;
    }
    const opened = new Set<HTMLElement>();
    for (const row of rows) {
      if (layout === "ledger") {
        const box = boxFor(row);
        if (!opened.has(box)) {
          opened.add(box);
          animHeight(box, { from: startOf(box, rows), k: SPR.ledger.arrive });
        }
        wash(row);
        continue;
      }
      const card = row.closest<HTMLElement>(".v-activity-feed__cluster");
      if (card && known.has(card) && closedBurst(row)) {
        // a closed burst takes the line without opening
        if (!opened.has(card)) {
          opened.add(card);
          animHeight(card, { k: SPR.bursts.gulp, kick: 160 });
        }
        continue;
      }
      const box = boxFor(row);
      row.setAttribute("data-slide", "");
      let slid = false;
      const slide = (p: number) => {
        if (slid || p <= 0.35) return;
        slid = true;
        rows.forEach(
          (r) => box.contains(r) && r.removeAttribute("data-slide"),
        );
      };
      if (opened.has(box)) continue;
      opened.add(box);
      animHeight(box, {
        from: startOf(box, rows),
        k: SPR.bursts.arrive,
        onFrame: slide,
      });
    }
  }

  /* ---------- Show more: at most three items unfurl with a short stagger ---------- */
  function unfurl(revealed: string[]) {
    const rows = revealed
      .slice(0, T.unfurlMax)
      .map((id) => rowOf(id))
      .filter((r): r is HTMLElement => !!r);
    const boxes: { box: HTMLElement; rows: HTMLElement[]; from: number }[] = [];
    for (const row of rows) {
      const box = boxFor(row),
        found = boxes.find((b) => b.box === box);
      if (found) found.rows.push(row);
      else boxes.push({ box, rows: [row], from: 0 });
    }
    for (const b of boxes) {
      b.from = startOf(b.box, rows);
      hold(b.box, b.from);
    }
    if (layout === "thread")
      for (const row of rows) {
        const id = row.dataset.activityEntry ?? "",
          prev = ids[ids.indexOf(id) - 1];
        row.setAttribute("data-mark", "hidden");
        row.setAttribute("data-arriving", "");
        markScale.set(row, 0);
        if (prev !== undefined) holdThread(`${prev}>${id}`, "down");
      }
    if (layout === "bursts")
      rows.forEach((r) => r.setAttribute("data-slide", ""));
    const go = ({ box, rows: inside, from }: (typeof boxes)[number]) => {
      let shown = false,
        threaded = false;
      if (layout === "ledger")
        return animHeight(box, { from, k: SPR.ledger.unfurl });
      if (layout === "bursts")
        return animHeight(box, {
          from,
          k: SPR.bursts.unfurl,
          onFrame: (p) => {
            if (shown || p <= 0.3) return;
            shown = true;
            inside.forEach((r) => r.removeAttribute("data-slide"));
          },
        });
      animHeight(box, {
        from,
        k: SPR.thread.unfurl,
        onFrame: (p) => {
          if (!shown && p > 0.5) {
            shown = true;
            inside.forEach((r) => r.removeAttribute("data-arriving"));
          }
          if (threaded || p <= 0.6) return;
          threaded = true;
          // the thread grows on from the marker above, then the marker pops in
          const next = (i: number) => {
            const row = inside[i];
            if (!row) return;
            const id = row.dataset.activityEntry ?? "",
              prev = ids[ids.indexOf(id) - 1],
              key = `${prev}>${id}`,
              gr = grow.get(key);
            if (!gr) {
              markIn(row);
              return next(i + 1);
            }
            const upper = prev !== undefined ? rowOf(prev) : null;
            until(
              () => !upper || !upper.hasAttribute("data-mark"),
              () => {
                releaseThread(key, gr, SPR.thread.threadDown);
                until(
                  () => gr.s.x > 0.85,
                  () => {
                    markIn(row);
                    next(i + 1);
                  },
                );
              },
            );
          };
          next(0);
        },
      });
    };
    boxes.forEach((b, i) =>
      i ? after(i * T.unfurlStagger, () => go(b)) : go(b),
    );
  }

  /* ---------- breathing: only the newest live arrival, only while it can be seen ---------- */
  function applyBreath() {
    host
      .querySelectorAll("[data-breath]")
      .forEach((el) => el.removeAttribute("data-breath"));
    if (breathId === null || !breatheOn || ids[0] !== breathId) return;
    rowOf(breathId)?.setAttribute("data-breath", "");
  }
  function breathe(id: string) {
    cancelMotion(breathTimer);
    breathId = id;
    breathTimer = scheduleMotion(() => {
      breathTimer = null;
      breathId = null;
      applyBreath();
    }, T.breathFor);
  }

  /** Finish every episode at its rest paint: used for quiet, hidden tabs and layout changes. */
  function settle() {
    gen++;
    timers.forEach(cancelMotion);
    timers.clear();
    waits.clear();
    const boxes = [...heights];
    heights.clear();
    for (const [el, a] of boxes) {
      if (a.to === "auto") {
        el.style.height = "";
        el.removeAttribute("data-moving");
      }
      a.done?.();
    }
    host
      .querySelectorAll<HTMLElement>("[data-moving]:not([data-leaving])")
      .forEach((el) => {
        el.style.height = "";
        el.removeAttribute("data-moving");
      });
    const running = [...anims];
    anims.clear();
    running.forEach((a) => a.done?.());
    blobs.forEach((b) => b.el.remove());
    blobs.clear();
    grow.clear();
    markScale.clear();
    host
      .querySelectorAll<HTMLElement>(
        "[data-mark],[data-arriving],[data-slide]",
      )
      .forEach((el) => {
        el.removeAttribute("data-mark");
        el.removeAttribute("data-arriving");
        el.removeAttribute("data-slide");
      });
    host
      .querySelectorAll<HTMLElement>(".v-activity-feed__mark")
      .forEach((m) => (m.style.transform = ""));
    host
      .querySelectorAll<HTMLElement>(".v-activity-feed__wash[data-on]")
      .forEach((w) => {
        w.style.clipPath = "";
        w.removeAttribute("data-on");
      });
  }

  const scene: Scene = {
    frame(dt) {
      heights.forEach((a, el) => stepHeight(el, a, dt));
      anims.forEach((a) => {
        if (a.tick(dt)) return;
        anims.delete(a);
        a.done?.();
      });
      draw();
      waits.forEach((w) => {
        w.left -= dt;
        if (!w.when() && w.left > 0) return;
        waits.delete(w);
        w.run();
      });
      return heights.size > 0 || anims.size > 0 || waits.size > 0;
    },
  };

  return {
    sync(next: ActivitySync) {
      const relayout = next.layout !== layout;
      if (next.layer !== layer) {
        layer = next.layer;
        segments.length = 0;
        spine = seeds = null;
        if (layer) {
          layer.replaceChildren();
          spine = layer.appendChild(document.createElementNS(NS, "g"));
          seeds = layer.appendChild(document.createElementNS(NS, "g"));
        }
      }
      layout = next.layout;
      brand = next.brand;
      allowed = next.allowed;
      breatheOn = next.breathe;
      const before = new Set(ids);
      const hadRows = ids.length > 0;
      ids = [...next.ids];
      if (!started || relayout || !allowed || document.hidden) {
        settle();
        if (relayout) breathId = null;
      } else {
        const fresh = ids.filter((id) => !before.has(id));
        const firstKept = ids.findIndex((id) => before.has(id));
        const top = firstKept < 0 ? ids.length : firstKept;
        const arrivals = fresh.filter((id) => ids.indexOf(id) < top);
        const shown = new Set(next.revealed);
        const reveals = fresh.filter(
          (id) => shown.has(id) && ids.indexOf(id) >= top,
        );
        // a bulk load or a first paint appears at rest; live prepends arrive
        if (arrivals.length && arrivals.length <= T.unfurlMax) {
          arrive(arrivals);
          if (hadRows || arrivals.length === 1) breathe(arrivals[0]);
        }
        if (reveals.length) unfurl(reveals);
      }
      started = true;
      host
        .querySelectorAll(".v-activity-feed__day,.v-activity-feed__cluster")
        .forEach((el) => known.add(el));
      applyBreath();
      draw();
      wake();
    },
    measure() {
      draw();
    },
    /** Close a removed box on a spring, then let presence unmount it. */
    leave(el: HTMLElement, done: () => void) {
      if (!allowed || document.hidden || !el.isConnected) return done();
      if (layout === "thread" && el.matches(ROW)) {
        const ms = S(SPR.markOut, markScale.get(el) ?? 1);
        ms.v = 2.5;
        ms.to = 0;
        tween([ms], () => setMark(el, Math.max(0, ms.x)));
      }
      animHeight(el, { to: 0, k: SPR.remove, done });
      draw();
    },
    /** A removal reversed while it was still closing. */
    stay(el: HTMLElement) {
      const a = heights.get(el);
      if (!a || a.to !== 0) return;
      a.done = undefined;
      animHeight(el, { k: SPR.restore });
      if (el.matches(ROW)) setMark(el, 1);
    },
    /** Open or close a burst on a spring; false lets the native toggle happen instantly. */
    toggle(details: HTMLDetailsElement) {
      const card = details.parentElement;
      if (!allowed || document.hidden || !card) return false;
      if (details.open && !details.hasAttribute("data-closing")) {
        const full = card.getBoundingClientRect().height;
        details.open = false;
        const closed = natural(card);
        details.open = true;
        details.setAttribute("data-closing", "");
        animHeight(card, {
          from: full,
          to: closed,
          k: SPR.bursts.close,
          done: () => {
            details.removeAttribute("data-closing");
            details.open = false;
            card.style.height = "";
            card.removeAttribute("data-moving");
          },
        });
      } else {
        details.removeAttribute("data-closing");
