    );
    attr(haloEl, "opacity", painting ? f3(clamp((hs - 0.6) / 0.4)) : "0");
    attr(haloEl, "data-tone", halo.danger ? "danger" : null);
    drawBlob(body);
    marks.forEach(drawBlob);
  }

  /* the clock */
  function frame(dt: number) {
    if (!painting) return false;
    for (const s of springs()) if (!rest(s)) spring(s, dt);
    // Turns are in degrees: the shared 0.0008 snap would hold an invisible creep for about a second.
    for (const b of [body, ...marks])
      if (Math.abs(b.rot.to - b.rot.x) < 0.1 && Math.abs(b.rot.v) < 1) set(b.rot, b.rot.to);    hook?.();
    draw();
    for (const w of waits.slice()) if (w.g !== gen || w.when?.()) done(w);
    const active =
      waits.length > 0 || !!hook || springs().some((s) => !rest(s));
    if (!active && !busy) release(true);
    return active;
  }
  function done(w: Wait) {
    const i = waits.indexOf(w);
    if (i < 0) return;
    waits.splice(i, 1);
    cancelMotion(w.timer);
    w.r();
  }
  const wait = (ms: number, when?: () => boolean) =>
    new Promise<void>((r) => {
      const w: Wait = { g: gen, when, r, timer: scheduleMotion(() => done(w), ms) };
      waits.push(w);
      wake();
    });
  const sleep = (ms: number) => wait(ms);
  const until = (when: () => boolean, maxMs = 3000) => wait(maxMs, when);

  /* ownership: static markers hide only while this layer paints them */
  function own(from: number, to: number) {
    for (let i = from; i <= to; i++) {
      const marker = part(i, "marker");
      if (marker) {
        owned.set(i, marker);
        marker.setAttribute(OWNED, "");
      }
      const connection = i < to ? part(i, "connection") : null;
      if (connection) {
        ownedSegs.set(i, connection);
        connection.setAttribute(OWNED, "");
      }
    }
  }
  const turnOf = (i: number) =>
    parseFloat(part(i, "marker")?.style.getPropertyValue("--mp-turn") ?? "") ||
    0;
  function setTurn(i: number, deg: number) {
    const m = part(i, "marker");
    if (m) turn(m, deg);
  }
  function turn(m: HTMLElement | SVGElement, deg: number) {
    const d = ((deg % 360) + 360) % 360;
    if (d < 0.05 || d > 359.95) m.style.removeProperty("--mp-turn");
    else m.style.setProperty("--mp-turn", `${d.toFixed(2)}deg`);
  }
  /**
   * Hand every owned marker back to static paint. At rest the layer shows the same outline,
   * so `keep` carries its turn over; a cancelled beat drops to the upright rest paint.
   */
  function release(keep: boolean) {
    for (const [i, marker] of owned) {
      const b =
        body.show && body.seg < 0 && body.at === i
          ? body
          : marks[i]?.show
            ? marks[i]
            : null;
      turn(marker, keep && b ? b.rot.x : 0);
      marker.removeAttribute(OWNED);
    }
    for (const connection of ownedSegs.values()) connection.removeAttribute(OWNED);
    owned.clear();
    ownedSegs.clear();
    painting = false;
    hook = null;
    const pending = waits;
    waits = [];
    pending.forEach((w) => {
      cancelMotion(w.timer);
      w.r();
    });
    busy = false;
    neck.n = 0;
    ep = null;
    gBlobs.removeAttribute("filter");
    body.show = false;
    marks.forEach((mk) => (mk.show = false));
    rings.forEach((r) => (r.show = false));
    draw();
  }

  /* blobs start each beat as the rest paint of the item they stand on */
  function resetBlob(b: Blob) {
    b.seg = -1;
    b.st = 0;
    b.later = undefined;
    tune(b.p, ...EXPRESSIVE);
    set(b.p, 0);
    tune(b.oy, 300, 0.5);
    set(b.oy, 0);
    tune(b.s, 260, 0.6);
    set(b.s, 1);
    tune(b.q, 300, 0.35);
    set(b.q, 0);
    tune(b.m, 240, 0.6);
    set(b.m, 1);
    tune(b.rot, 300, 0.4);
    set(b.co, 0);
  }
  const doneShape = () => (travel === "seed" ? SHAPES.star : SHAPES.done);
  const doneGlyph = (): Glyph => (travel === "seed" ? "none" : "check");
  /** Take over the static paint of items from..to (inclusive) and start a new beat. */
  function begin(from: number, to: number) {
    if (!painting) {
      painting = true;
      ink = segs.map(() => 0);
      neck.n = 0;
      set(sep, 0);
      resetBlob(body);
      set(body.rot, turnOf(at));
      body.show = true;
      body.at = at;
      body.A = body.B = mood ? SHAPES.needs : SHAPES.pebble;
      body.fill = mood ? "danger" : "pink";
      body.glyph = mood ? "bang" : "core";
      tune(halo.s, 220, 0.5);
      set(halo.s, 1);
      halo.danger = mood;
    }
    for (let i = from; i <= to; i++)
      if (!owned.has(i) && i !== at) rings[i].show = true;
    own(from, to);
    busy = true;
    return ++gen;
  }

  /* ---------- choreography shared by every character (ported from the step-travel prototype) ---------- */
  function handOff(mk: Blob, b: Blob) {
    // the step's mark takes over the body's exact look, so nothing pops
    mk.show = true;
    mk.seg = -1;
    mk.at = b.at;
    for (const k of ["oy", "s", "q", "rot"] as const)
      Object.assign(mk[k], { ...b[k] });
    mk.A = mk.B = currentPts(b);
    set(mk.m, 1);
    mk.fill = b.fill;
    mk.glyph = b.glyph;
    mk.st = b.st;
    mk.later = undefined;
  }
  function morphTo(b: Blob, shape: Pts, k: number, z: number) {
    b.A = currentPts(b);
    b.B = shape;
    set(b.m, 0);
    tune(b.m, k, z).to = 1;
  }
  function harden(mk: Blob) {
    morphTo(mk, SHAPES.done, 240, 0.6);
    mk.fill = "olive";
    tune(mk.s, 260, 0.45).to = 1;
    mk.glyph = "check";
  }
  const haloOut = () => {
    tune(halo.s, 420, 1).to = 0.6;
  };
  function haloBloom() {
    halo.danger = body.fill === "danger";
    set(halo.s, 0.6);
    tune(halo.s, 200, 0.5).to = 1;
  }
  function startTrack(b: Blob, seg: number, l0: number) {
    b.seg = seg;
    b.l0 = l0;
    b.l1 = spanTo(seg, ep!.to);
    tune(b.p, ...EXPRESSIVE);
    set(b.p, 0);
  }
  // 1. Anticipation: gather and squash, about 120 ms.
  async function anticipate(b: Blob) {
    tune(b.q, 900, 1).to = 0.13;
    tune(b.oy, 900, 1).to = -3;
    tune(b.s, 900, 1).to = 0.95;
    await sleep(120);
    tune(b.q, 300, 0.35).to = 0;
    tune(b.oy, 260, 0.55).to = 0;
    tune(b.s, 300, 0.5).to = 1;
  }
  // A step the body passes on a retargeted run blooms its done mark as the body goes by.
  function leaveMark(i: number) {
    const mk = marks[i];
    resetBlob(mk);
    mk.show = true;
    mk.at = i;
    mk.A = mk.B = doneShape();
    mk.fill = "olive";
    mk.glyph = doneGlyph();
    set(mk.rot, 0);
    set(mk.s, 0.55);
    tune(mk.s, 260, 0.45).to = 1;
    mk.q.v -= 1.2;
  }
  // 2-3. Travel on the expressive spring; arrival squash settles in ~625 ms (k 300, z .35).
  function travelHook(b: Blob, extra?: (len: number) => void) {
    return () => {
      const e = ep!,
        len = lenOf(b),
        span = b.l1 - b.l0;
      let start = 0;
      for (let i = b.seg; i < e.to; i++) {
        ink[i] = clamp((len - start) / segs[i].L);
        start += segs[i].L;
        if (len > start - 9) {
          rings[i + 1].show = false;
          if (i + 1 < e.to && !e.passed.has(i + 1)) {
            e.passed.add(i + 1);
            leaveMark(i + 1);
          }
        }
      }
      if (!e.landed) b.st = Math.min(0.3, (Math.abs(b.p.v) * span) / 1900);
      else b.st *= 0.8;
      if (!e.landed && b.p.x >= 1) {
        e.landed = true;
        b.q.v += Math.min(4.2, Math.abs(b.p.v) * span * 0.0055);
        haloBloom();
        gBlobs.removeAttribute("filter"); // the goo joins bodies only while they travel
      }
      extra?.(len);
    };
  }
  // Park the body on its destination; any residual overshoot moves into oy, so nothing jumps.
  function park(b: Blob) {
    if (b.seg < 0 || !ep) return;
    b.oy.x += lenOf(b) - b.l1;
    b.oy.v += b.p.v * (b.l1 - b.l0);
    b.seg = -1;
    b.at = ep.to;
    b.st = 0;
    set(b.p, 0);
    hook = null;
    neck.n = 0;
    set(sep, 0);
    gBlobs.removeAttribute("filter");
  }
  function settled(g: number) {
    if (g !== gen) return;
    busy = false;
    reconcile();
    wake();
  }
  async function finishInPlace(mk: Blob, b: Blob, g: number) {
    // the last step has nowhere to go: the body becomes its own mark
    b.show = false;
    haloOut();
    if (travel === "seed") {
      morphTo(mk, SHAPES.star, 220, 0.55);
      mk.fill = "olive";
      mk.glyph = "none";
      tune(mk.rot, 170, 0.5).to = Math.ceil((mk.rot.x + 45) / 90) * 90;
    } else {
      harden(mk);
      mk.s.x = Math.min(mk.s.x, 0.9);
    }
    at = -1;
    await until(() => rest(mk.m) && rest(mk.s) && rest(mk.rot));
    settled(g);
  }

  /* droplet: a neck pulls along the spine, thins and snaps; the drop left behind blooms into the done mark */
  async function droplet(from: number, g: number) {
    const b = body,
      mk = marks[from];
    await anticipate(b);
    if (g !== gen) return;
    handOff(mk, b);
    mk.glyph = "none";
    if (!ep) return finishInPlace(mk, b, g);
    gBlobs.setAttribute("filter", `url(#${gooId})`);
    tune(mk.s, 300, 0.9).to = 0.56;
    haloOut();
    startTrack(b, from, 0);
    b.p.to = 1;
    neck.seg = from;
    let snap = false;
    hook = travelHook(b, (len) => {
      neck.d = len;
      neck.n = clamp(1 - len / (segs[from].L * 0.6));
      if (!snap && neck.n < 0.14 && len > 12) {
        snap = true;
        harden(mk);
        mk.q.v -= 2.4;
        b.q.v -= 1.2;
      }
    });
    await until(() => !!ep?.landed && rest(b.p) && rest(b.q));
    if (g !== gen) return;
    park(b);
    settled(g);
  }

  /* seed: the seed becomes the four-point star; a new seed buds off it and rolls to the next step */
  async function seed(from: number, g: number) {
    const b = body,
      mk = marks[from];
    await anticipate(b);
    if (g !== gen) return;
    handOff(mk, b);
    b.show = false;
    if (!ep) return finishInPlace(mk, b, g);
    haloOut();
    morphTo(mk, SHAPES.star, 220, 0.55);
    mk.fill = "olive";
    mk.glyph = "none";
    tune(mk.rot, 170, 0.5).to = Math.ceil((mk.rot.x + 45) / 90) * 90;
    tune(mk.s, 300, 0.5);
    mk.s.v += 1.4;
    await sleep(150);
    if (g !== gen) return;
    // the bud grows out from behind the star's lower point
    b.show = true;
    b.A = b.B = SHAPES.pebble;
    set(b.m, 1);
    b.fill = "pink";
    b.glyph = "core";
    set(b.rot, 0);
    set(b.q, 0);
    set(b.oy, 0);
    set(b.s, 0);
    tune(b.s, 320, 0.7).to = 0.46;
    startTrack(b, from, 8);
    await sleep(170);
    if (g !== gen) return;
    b.p.to = 1;
    tune(b.s, 110, 0.85).to = 1;
    tune(b.co, 200, 0.8).to = 5.5; // the nucleus sits off-centre while it rolls, so the turn is visible
    let lastLen = lenOf(b);
    hook = travelHook(b, (len) => {
      // rolling: turn = distance / radius, so the overshoot rolls it back
      set(b.rot, b.rot.x + ((len - lastLen) / (R * Math.max(0.35, b.s.x))) * 57.2958);
      lastLen = len;
      if (ep?.landed && b.co.to) tune(b.co, 220, 0.6).to = 0;
    });
    await until(
      () => !!ep?.landed && rest(b.p) && rest(b.s) && rest(b.q) && rest(b.co),
    );
    if (g !== gen) return;
    park(b);
    settled(g);
  }

  /* division: the body elongates and pinches in two; one half hardens, the daughter travels */
  async function division(from: number, g: number) {
    const b = body,
      mk = marks[from];
    await anticipate(b);
    if (g !== gen) return;
    handOff(mk, b);
    if (!ep) {
      mk.glyph = "none";
      return finishInPlace(mk, b, g);
    }
    gBlobs.setAttribute("filter", `url(#${gooId})`);
    haloOut();
    tune(mk.s, 260, 0.9).to = 0.8;
    tune(b.s, 260, 0.9).to = 0.8;
    set(sep, 0);
    sep.to = 36;
    startTrack(b, from, 0);
    let pinched = false;
    const travelling = travelHook(b, () => {
      // The half keeps the body's colour until the goo lets go, so pink never blends into olive.
      if (!mk.later) return;
      const [x0, y0] = pos(mk),
        [x1, y1] = pos(b);
      if (Math.hypot(x1 - x0, y1 - y0) > R * (mk.s.x + b.s.x) + 8) {
        mk.fill = mk.later.fill;
        mk.glyph = mk.later.glyph;
        mk.later = undefined;
      }
    });
    hook = () => {
      if (pinched) return travelling();
      const e = clamp(sep.x / 36);
      b.l0 = sep.x * 0.82;
      set(mk.oy, -sep.x * 0.18);
      mk.st = b.st = 0.22 * Math.sin(Math.PI * e); // the cell elongates along the spine as it divides
      ink[from] = clamp(b.l0 / segs[from].L);
      if (sep.x > 30.5) {
        pinched = true;
        mk.q.x = -mk.st * 0.85;
        mk.st = 0; // the stretch snaps back as a wobble
        harden(mk);
        mk.later = { fill: "olive", glyph: "check" };
        mk.fill = b.fill;
        mk.glyph = "none";
        tune(mk.oy, 220, 0.6).to = 0;
        b.q.x = -b.st * 0.85;
        b.p.v = (sep.v * 0.82) / (b.l1 - b.l0);
        b.p.to = 1;
        tune(b.s, 140, 0.8).to = 1;
      }
    };
    await until(() => !!ep?.landed && rest(b.p) && rest(b.q) && rest(b.s));
    if (g !== gen) return;
    if (mk.later) {
      mk.fill = mk.later.fill;
      mk.glyph = mk.later.glyph;
      mk.later = undefined;
    }
    park(b);
    settled(g);
  }

  function run(from: number, to: number) {
    park(body);
    const g = begin(from, Math.max(from, to));
    ep = to < 0 ? null : { to, landed: false, passed: new Set() };
    if (to >= 0) at = to;
    if (body.fill === "danger") {
      // finished straight from needing an action: the traveller is working again
      morphTo(body, SHAPES.pebble, 240, 0.55);
      body.fill = "pink";
      body.glyph = "core";
      halo.danger = false;
    }
    mood = false;
    void { seed, droplet, division }[travel](from, g);
  }
  function recoil() {
    park(body);
    const g = begin(at, at),
      b = body;
    mood = true;
    // a flinch back up the spine, a contraction and a shudder, then the danger tone and the needs shape
    tune(b.oy, 380, 0.42).v -= 240;
    tune(b.s, 260, 0.5).v -= 2.2;
    tune(b.q, 300, 0.35).v -= 1.6;
    tune(b.rot, 420, 0.3).v += 380;
    b.rot.to = Math.round(b.rot.x / 120) * 120;
    morphTo(b, SHAPES.needs, 260, 0.5);
    b.fill = "danger";
    b.glyph = "bang";
    halo.danger = true;
    tune(halo.s, 300, 0.4).v -= 2.5;
    void until(() => [b.oy, b.s, b.q, b.rot, b.m].every(rest)).then(() =>
      settled(g),
    );
  }
  function retry() {
    park(body);
    const g = begin(at, at),
      b = body;
    mood = false;
    morphTo(b, SHAPES.pebble, 240, 0.55);
    b.fill = "pink";
    b.glyph = "core";
    b.q.v += 2.4;
    b.s.v += 1.2;
    haloBloom();
    void until(() => [b.oy, b.s, b.q, b.rot, b.m].every(rest)).then(() =>
      settled(g),
    );
  }

  // Instant: drop any beat in flight and show the static paint.
  function anchor() {
    gen++;
    if (painting) release(false);
    at = states.findIndex(isActive);
    mood = states[at] === "needs";
  }
  function act(plan: TravelPlan) {
    if (plan.kind === "anchor") return anchor();
    if (plan.kind === "none") return;
    const inFlight = !!ep && !ep.landed && busy;
    if (plan.kind === "handoff" && inFlight) {
      // retarget from the current position and velocity
      const b = body,
        e = ep!;
      e.to = plan.to;
      at = plan.to;
      for (let i = plan.from + 1; i <= plan.to; i++)
        if (!e.passed.has(i)) rings[i].show = true;
      own(plan.from, plan.to);
      if (b.seg >= 0) {
        const len = lenOf(b),
          v = b.p.v * (b.l1 - b.l0);
        b.l0 = len;
        b.l1 = spanTo(b.seg, plan.to);
        b.p.x = 0;
        b.p.v = v / Math.max(1, b.l1 - b.l0);
      }
      return;
    }
    if (inFlight) return; // the beat in flight lands first, then reconcile() catches up
    if (plan.kind === "handoff") return run(plan.from, plan.to);
    if (plan.kind === "finish") return run(plan.at, -1);
    if (plan.kind === "recoil") return recoil();
    retry();
  }
  function reconcile() {
    if (at >= 0) act(planTravel(ids, ids, states, at, mood));
  }

  return {
    sync(next: Sync) {
      const variant = next.travel !== travel;
      const fresh =
        variant ||
        next.axis !== axis ||
        next.ids.length !== ids.length ||
        next.ids.some((id, i) => id !== ids[i]);
      const instant = fresh || !next.allowed || document.hidden;
      const before = new Map(ids.map((id, i) => [id, states[i]]));
      const prevIds = ids;
      if (instant && painting) {
        gen++;
        release(false);
      }
      ids = next.ids;
      states = next.states;
      travel = next.travel;
      axis = next.axis;
      measure();
      const changed = ids.map(
        (id, i) => variant || before.get(id) !== states[i],
      );
      const plan: TravelPlan = instant
        ? { kind: "anchor" }
        : changed.some(Boolean)
          ? planTravel(prevIds, ids, states, at, mood)
          : { kind: "none" };
      // The layer sets the final turn of whatever it animates; everything else rests upright.
      const lo =
          plan.kind === "handoff" ? plan.from : "at" in plan ? plan.at : -1,
        hi = plan.kind === "handoff" ? plan.to : lo;
      changed.forEach(
        (c, i) => c && !owned.has(i) && (i < lo || i > hi) && setTurn(i, 0),
      );
      act(plan);
      draw();
      wake();
    },
    measure() {
      if (!painting) return;
      measure();
      draw();
    },
    attach() {
      scenes.add(scene);
    },
    destroy() {
      gen++;
      if (painting) release(false);
      scenes.delete(scene);
      svg.replaceChildren();
    },
  };
}

/**
 * Drives the decorative travel layer for one sibling list. The caller renders the static
 * paint; this only borrows it while a beat plays and always hands back the same outline.
 */
export function useMilestoneTravel(
  host: React.RefObject<HTMLElement | null>,
  layer: React.RefObject<SVGSVGElement | null>,
  next: Sync,
) {
  const id = React.useId();
  const scene = React.useRef<ReturnType<typeof createScene> | null>(null);
  const sync = React.useEffectEvent(() => scene.current?.sync(next));
  React.useLayoutEffect(() => {
    if (!host.current || !layer.current) return;
    const s = createScene(
      host.current,
      layer.current,
      `mp-goo-${id.replace(/[^\w-]/g, "")}`,
    );
    s.attach();
    scene.current = s;
    const observer = new ResizeObserver(() => s.measure());
    observer.observe(host.current);
    return () => {
      observer.disconnect();
      s.destroy();
      scene.current = null;
    };
  }, [host, layer, id]);
  const key = `${next.ids.join("\u0001")}\u0002${next.states.join(",")}`;
  // Declared after the scene effect, so on mount the scene exists before its first sync.
  React.useLayoutEffect(() => {
    sync();
  }, [key, next.travel, next.axis, next.allowed]);
}

@layer cojeev-states {
.v-activity-feed[data-slot] {
  min-width: 0;
  width: 100%;
  color: var(--v-text);
  background: var(--v-paper);
  padding: var(--s-7);
  border: 1px solid var(--v-border);
  border-radius: var(--r-panel) var(--r-panel) var(--r-sm) var(--r-panel);
}
.v-activity-feed__header {
  display: grid;
  gap: var(--s-2);
  margin-block-end: var(--s-5);
}
.v-activity-feed__header :is(h3, p) {
  margin: 0;
}
.v-activity-feed__heading {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--s-3);
}
.v-activity-feed__body {
  position: relative;
}
.v-activity-feed__list,
.v-activity-feed__clusters,
.v-activity-feed__rows {
  display: grid;
  list-style: none;
  margin: 0;
  padding: 0;
  min-width: 0;
}
/* Rows, runs and days carry no padding of their own, so each can close to nothing. */
.v-activity-feed__entry,
.v-activity-feed__cluster,
.v-activity-feed__day {
  position: relative;
  min-width: 0;
}
.v-activity-feed :is(.v-activity-feed__entry, .v-activity-feed__cluster, .v-activity-feed__day)::marker {
  content: none;
}
.v-activity-feed__entry {
  outline-offset: 3px;
  border-radius: var(--r-sm);
}
.v-activity-feed__entry:focus-visible {
  outline: 2px solid var(--v-blue);
}
.v-activity-feed__inner {
  position: relative;
  min-width: 0;
}
/* Only while a box springs open or closed: paint stays inside it. */
.v-activity-feed [data-moving] {
  overflow: clip;
}
.v-activity-feed__portrait {
  position: relative;
  display: flex;
  justify-content: center;
}
.v-activity-feed__mark {
  position: relative;
  display: grid;
  place-items: center;
  inline-size: 28px;
  block-size: 28px;
  isolation: isolate;
}
.v-activity-feed__mark > [data-slot] {
  position: relative;
  z-index: 1;
}
.v-activity-feed [data-mark="hidden"] .v-activity-feed__mark {
  opacity: 0;
}
.v-activity-feed__group {
  margin: 0;
  color: var(--v-text-2);
  font-size: var(--fs-caps);
  font-weight: var(--fw-semibold);
  letter-spacing: var(--ls-caps, 0.08em);
  text-transform: uppercase;
  position: relative;
  z-index: 1;
  padding: var(--s-4) 0 var(--s-1);
}
.v-activity-feed__list > :first-child > .v-activity-feed__group {
  padding-block-start: 0;
}
.v-activity-feed__header
  .v-activity-feed__heading
  [data-slot="typography-title"] {
  font-size: var(--fs-title);
  letter-spacing: -0.035em;
}
/* The product's own entries carry the four-point brand star. */
.v-activity-feed__marker svg {
  display: block;
  inline-size: 30px;
  block-size: 30px;
  margin: -1px;
  overflow: visible;
  flex: none;
}
.v-activity-feed__marker path {
  fill: var(--v-olive);
}
.v-activity-feed__content[data-slot] {
  position: relative;
  z-index: 1;
  row-gap: 2px;
  min-width: 0;
  align-content: start;
  transition:
    opacity var(--t-max) var(--enter),
    translate var(--t-max) var(--enter);
}
.v-activity-feed [data-arriving] .v-activity-feed__content {
  opacity: 0;
}
.v-activity-feed [data-slide] .v-activity-feed__content {
  opacity: 0;
  translate: 0 -8px;
}
/* A removed row fades inside its own closing height. */
.v-activity-feed [data-leaving] > * {
  opacity: 0;
  transition: opacity var(--t-element) var(--exit);
}
.v-activity-feed__entry-heading {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--s-2) var(--s-3);
  min-width: 0;
}
.v-activity-feed__title[data-slot] {
  display: block;
  overflow: visible;
  -webkit-line-clamp: unset;
  font-size: var(--fs-body);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.v-activity-feed__badge[data-slot] {
  flex-shrink: 0;
  max-width: 100%;
  min-height: 20px;
  height: auto;
  padding-block: 3px;
  white-space: normal;
  line-height: 1.2;
}
.v-activity-feed__description[data-slot] {
  font-size: var(--fs-control);
  line-height: 1.55;
  max-width: 68ch;
  overflow-wrap: anywhere;
}
.v-activity-feed__description :first-child {
  margin-block-start: 0;
}
.v-activity-feed__description :last-child {
  margin-block-end: 0;
}
.v-activity-feed__meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0 var(--s-2);
  color: var(--v-text-2);
  min-width: 0;
}
/* The one breathing thing in the ledger and bursts: the newest entry while it is fresh. */
.v-activity-feed__live {
  display: none;
  inline-size: 6px;
  block-size: 6px;
  border-radius: 50%;
  background: var(--v-pink-deep);
  flex: none;
}
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  [data-breath]
  .v-activity-feed__live {
  display: inline-block;
  animation: v-activity-dot var(--breath) ease-in-out infinite;
}
@keyframes v-activity-dot {
  50% {
    opacity: 0.4;
    transform: scale(0.7);
  }
}
.v-activity-feed__meta :is(time, span) {
  overflow-wrap: anywhere;
}
.v-activity-feed__details {
  display: grid;
  gap: var(--s-2);
  margin-block-start: var(--s-1);
  min-width: 0;
  overflow-wrap: anywhere;
}
.v-activity-feed__footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--s-3);
  padding-block-start: var(--s-4);
  border-block-start: 1px solid var(--v-edge);
}
.v-activity-feed__footer > [data-slot="button"] {
  min-height: 44px;
  width: auto;
}
/* ---------- thread: one row per entry on a living thread ---------- */
.v-activity-feed[data-variant="thread"] .v-activity-feed__group {
  padding-inline-start: calc(36px + var(--s-4));
}
.v-activity-feed[data-variant="thread"] .v-activity-feed__inner {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  column-gap: var(--s-4);
  padding-block: var(--s-3) var(--s-4);
}
.v-activity-feed[data-variant="thread"] [data-breath] .v-activity-feed__mark::before {
  content: "";
  position: absolute;
  inset: -6px;
  z-index: -1;
  border-radius: 43% 57% 49% 51% / 55% 44% 56% 45%;
  background: var(--v-pink);
  opacity: 0.2;
  animation: v-activity-halo var(--breath) ease-in-out infinite;
}
@keyframes v-activity-halo {
  50% {
    opacity: 0.36;
    transform: scale(1.1);
  }
}
/* Paint only, never a hit target: the spine and the blooming seed. */
.v-activity-feed__thread {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  overflow: visible;
  pointer-events: none;
  z-index: 3;
}
.v-activity-feed__spine {
  fill: none;
  stroke: var(--v-border);
  stroke-width: 1.5;
  stroke-linecap: round;
}
.v-activity-feed__seed {
  transition: fill 240ms var(--enter);
}
.v-activity-feed__seed[data-fill="pink"] {
  fill: var(--v-pink);
}
.v-activity-feed__seed[data-fill="olive"] {
  fill: var(--v-olive);
}

/* ---------- ledger and bursts share the compact row ---------- */
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  .v-activity-feed__content[data-slot] {
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: var(--s-3);
}
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  .v-activity-feed__content
  > * {
  grid-column: 1 / -1;
}
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  .v-activity-feed__content
  > .v-activity-feed__entry-heading {
  grid-column: 1;
}
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  .v-activity-feed__content
  > .v-activity-feed__meta {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  align-self: baseline;
  white-space: nowrap;
}
/* The run names the actor once; each row keeps it for assistive technology. */
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  :is(.v-activity-feed__who, .v-activity-feed__sep) {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.v-activity-feed:is([data-variant="ledger"], [data-variant="bursts"])
  .v-activity-feed__title[data-slot] {
  font-size: var(--fs-control);
}

/* ---------- ledger: dense runs, pinned day labels ---------- */
.v-activity-feed[data-variant="ledger"] .v-activity-feed__group {
  position: sticky;
  top: 0;
  z-index: 4;
  padding: var(--s-2) 0;
  background: var(--v-paper);
  box-shadow: 0 1px 0 var(--v-border);
}
.v-activity-feed[data-variant="ledger"] .v-activity-feed__cluster-inner {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  column-gap: var(--s-3);
  padding-block: var(--s-3);
}
.v-activity-feed[data-variant="ledger"]
  .v-activity-feed__cluster
  + .v-activity-feed__cluster
  .v-activity-feed__cluster-inner {
  box-shadow: inset 0 1px 0 var(--v-border);
}
.v-activity-feed[data-variant="ledger"] .v-activity-feed__portrait {
  padding-block-start: 1px;
}
.v-activity-feed__cluster-body {
  min-width: 0;
}
.v-activity-feed__cluster-name {
  margin: 0;
  font-size: var(--fs-small);
  font-weight: var(--fw-semibold);
  line-height: 1.5;
  color: var(--v-text);
}
.v-activity-feed[data-variant="ledger"] .v-activity-feed__inner {
  padding-block: 3px;
}
/* The ink wash marks a new line, then fades within one draw. */
.v-activity-feed__wash {
  position: absolute;
  inset: 0 calc(-1 * var(--s-2));
  z-index: 0;
  border-radius: var(--r-sm);
  background: var(--sel-bg);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--t-draw) var(--exit);
}
.v-activity-feed__wash[data-on] {
  opacity: 1;
  transition: none;
}

/* ---------- bursts: one card per actor's burst of updates ---------- */
.v-activity-feed[data-variant="bursts"] .v-activity-feed__cluster::before {
  content: "";
  position: absolute;
  inset: 0 0 var(--s-3);
  border-radius: var(--r-card-sm) var(--r-card-sm) var(--r-card-sm) var(--r-sm);
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
/* The card's bottom padding and the gap to the next card, kept inside the card's height. */
.v-activity-feed[data-variant="bursts"] .v-activity-feed__cluster::after {
  content: "";
  display: block;
  block-size: calc(var(--s-3) * 2);
}
.v-activity-feed__burst {
  position: relative;
}
.v-activity-feed__card-head {
  position: relative;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: var(--s-3);
  min-height: 28px;
  padding: var(--s-3) var(--s-4) 0;
  list-style: none;
  border-radius: var(--r-card-sm) var(--r-card-sm) var(--r-sm) var(--r-sm);
}
.v-activity-feed__card-head::-webkit-details-marker {
  display: none;
}
summary.v-activity-feed__card-head {
  cursor: pointer;
}
summary.v-activity-feed__card-head:focus-visible {
  outline: 2px solid var(--v-blue);
  outline-offset: 2px;
}
.v-activity-feed__card-who {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 var(--s-2);
  min-width: 0;
}
.v-activity-feed__card-name {
  font-weight: var(--fw-semibold);
  overflow-wrap: anywhere;
}
.v-activity-feed__card-count {
  font-size: var(--fs-meta);
  color: var(--v-text-2);
  font-variant-numeric: tabular-nums;
}
.v-activity-feed__chevron {
  inline-size: 16px;
  block-size: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  color: var(--v-text-2);
  transition: rotate var(--t-element) var(--enter);
}
.v-activity-feed__burst[open]:not([data-closing]) .v-activity-feed__chevron {
  rotate: 180deg;
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__rows {
  position: relative;
  padding: var(--s-1) var(--s-4) 0 calc(var(--s-4) + 28px + var(--s-3));
}
.v-activity-feed__cluster:has(> .v-activity-feed__burst:not([open]))
  > .v-activity-feed__rows {
  display: none;
}
.v-activity-feed[data-variant="bursts"] .v-activity-feed__inner {
  padding-block: var(--s-2);
}
.v-activity-feed[data-variant="bursts"]
  .v-activity-feed__entry
  + .v-activity-feed__entry
  .v-activity-feed__inner {
  box-shadow: inset 0 1px 0 var(--v-border);
}
.v-activity-feed[data-variant="bursts"]
  .v-activity-feed__entry:last-child
  .v-activity-feed__inner {
  padding-block-end: 0;
}

/* Quiet and reduced motion: instant, nothing loops. */
.v-activity-feed[data-motion-quiet] *,
.v-activity-feed[data-motion-quiet] *::before {
  animation: none;
  transition: none;
}
@media (prefers-reduced-motion: reduce) {
  .v-activity-feed *,
  .v-activity-feed *::before {
    animation: none;
    transition: none;
  }
}
@media (max-width: 480px) {
  .v-activity-feed[data-variant="thread"] .v-activity-feed__inner {
    column-gap: var(--s-3);
  }
  .v-activity-feed[data-variant="thread"] .v-activity-feed__group {
    padding-inline-start: calc(36px + var(--s-3));
  }
  .v-activity-feed__footer {
    justify-content: flex-start;
    gap: var(--s-3) var(--s-5);
  }
}
@media (max-width: 600px) {
  .v-activity-feed[data-slot] {
    padding: var(--s-5);
  }
}
@media (max-width: 560px) {
  .v-activity-feed__card-head {
    padding-inline: var(--s-3);
  }
  .v-activity-feed[data-variant="bursts"] .v-activity-feed__rows {
    padding-inline: var(--s-3);
  }
}
.v-activity-example {
  width: 100%;
  min-width: 0;
  display: grid;
  gap: var(--s-6);
}

}
